#' Batch Integration and Visualization for scRNA-seq with RPCA
#' @title Seu2Inter_Lisi_fixed: Recursive PCA Integration for Multiple scRNA-seq Samples
#' @description Perform recursive batch integration using Reciprocal PCA (RPCA) for large-scale scRNA-seq Seurat objects.
#'   Executes step-wise integration, PCA reduction, cell cycle scoring, scaling with regression, clustering, and UMAP visualization.
#'   Generates QC UMAP plots and saves all intermediate/final objects (Seurat, PCA, UMAP, metadata) to output directory.
#' @param input Character. Path to input directory containing reDl_scellist.RDS (preprocessed Seurat object list).
#' @param pcaNumber Numeric. Number of principal components to use for PCA and integration, default = 50.
#' @param batch_size Numeric. Number of samples per mini-batch for recursive integration, default = 5.
#' @returnType Seurat
#' @return A fully integrated and annotated Seurat object with:
#'   - Integrated assay via RPCA integration
#'   - Cell cycle scores (S.Score, G2M.Score)
#'   - Scaled data with regression (percent_mt, cell cycle, nCount_RNA)
#'   - PCA, UMAP reductions and cluster annotations
#'   - Saved output files (h5Seurat, RDS objects, UMAP plots)
#' @author MSY

library(SeuratObject)
library(SeuratDisk)
library(ggplot2)
library(Matrix)
library(future)
library(Seurat)

options(future.globals.maxSize = 200 * 1024^3)
plan("sequential")
options(Seurat.object.assay.version = "v4")
options(Seurat.memsafe = TRUE)

my_colors <- c(
  "#CC6666", "#6699CC", "#008280", "#BB0021", "#631879", "#E64B35",
  "#4DBBD5", "#00A087", "#3C5488", "#F39B7F", "#4A6FE3", "#B5BBE3",
  "#D6BCC0", "#BB7784", "#ED645A", "#8CD17D", "#86C7B4", "#9CD2ED", "#B07AA1",
  "#FF9D9A", "#DAA51B", "#F28E2B", "#D4DE9C", "#8DD593", "#B6992D", "#E58606",
  "#499894", "#FFBE7D", "#FABFD2", "#023FA5", "#CC95C0", "#7F7FD5", "#F3F9A7",
  "#9D7660", "#A0CBE8", "#134E5E", "#4AC29A", "#A8E063", "#F0E442", "#FEC260",
  "#EF9708", "#EAD3C6", "#ADE87C", "#9F8D89", "#DF5734", "#A44E89",
  "#B7DEEA", "#C4DAEC", "#C4612F", "#61BADA", "#7382BC", "#0FCFC0",
  "#8D689D", "#83AB8E", "#D8A0C0", "#ECE399", "#D33F6A", "#B95055",
  "#B85292", "#405993", "#64A776", "#A992C0", "#EA9994", "#007B7F", "#DF75AE", "#007ABA",
  "#A8C7E9", "#00B7CA", "#F37121", "#8CCA7C", "#8B58A4", "#FF5252", "#448AFF",
  "#00ACC1", "#FF9800", "#7B1FA2", "#FF4081", "#1E88E5", "#009688", "#5C6BC0",
  "#FF7043", "#5E35B1", "#43A047", "#FDD835", "#1976D2", "#FFA726",
  "#7E57C2", "#26A69A", "#FFEB3B", "#EC407A", "#3949AB", "#66BB6A", "#FFCA28",
  "#0288D1", "#8E24AA", "#42A5F5", "#AB47BC", "#29B6F6", "#689F38", "#FF5722",
  "#9C27B0", "#1DE9B6", "#994F00", "#8F7700", "#352A86", "#348DB2", "#E06377",
  "#FFB547", "#4E84C4", "#C4AD66", "#77BEDB", "#52BCA3", "#CC99C9",
  "#9ECAE1", "#CCCC99", "#F6B5C8", "#7ED379", "#78C679", "#D65F5F", "#8A9FD1",
  "#C6E090", "#7B685D", "#D9A404", "#998EC3", "#F1A340", "#661E01", "#B1DA99",
  "#A23B72", "#F18D9C", "#593C8C", "#C86070", "#9B5A56", "#727D8C", "#DC9497"
)
input <- "/public/home/yuxiaomingroup/msy/work/AID/juzhen/clean/result/"



Seu2Inter_Lisi_fixed <- function(input, pcaNumber=50, batch_size=5){

  targetfold <- paste0(input, pcaNumber)
  dir.create(targetfold, showWarnings=F, recursive=T)
  sce_list <- readRDS(file.path(input, "reDl_scellist.RDS"))

  plot_umap_gg <- function(Seurat_obj,reduction = "",group_by = "samples",
  pt_size = 0.04,sufix = "rpca",pname="",pcaNumber=pcaNumber) {
    
    
    df <- as.data.frame(Seurat_obj@reductions[[reduction]]@cell.embeddings)
    colnames(df) <- c("UMAP_1", "UMAP_2")
    df$Cluster<-Seurat_obj@meta.data$samples
    
    p <- ggplot(df, aes(x = UMAP_1, y = UMAP_2, color = Cluster)) +
      geom_point(size = pt_size, shape = 16, stroke = 0) +
      scale_color_manual(values = my_colors) +
      theme_classic() +
      theme(
        plot.background = element_blank(),
        panel.grid.major = element_blank(),
        panel.grid.minor = element_blank(),
        axis.title = element_blank(),
        axis.text = element_blank(),
        axis.ticks = element_blank(),
        axis.line = element_line(colour = "black",linewidth = 0.3),
        legend.position = "right", aspect.ratio = 1) +
      ggtitle(paste0("Cell count: ", ncol(Seurat_obj)," | Samples: ", length(unique(df$Cluster)))) +
      theme(
        plot.title = element_text(size = 10),
        legend.text = element_text(size = 6),
        legend.title = element_text(size = 6)
      ) +guides(color = guide_legend(ncol = 5, override.aes = list(size = 2.5)))
    
    filename <- file.path(targetfold, paste0(pcaNumber, sufix, "_", pname, "UMAP.pdf"))
    ggsave(filename, plot = p, width = 12.6, height = 11.5)}
 
  sce_list <- lapply(sce_list, function(x){
    x <- DietSeurat(x, counts=FALSE, data=TRUE, scale.data=FALSE)
    x <- ScaleData(x, verbose=F)
    x <- RunPCA(x, npcs=pcaNumber, verbose=F)
    return(x)
  })

  batches <- split(seq_along(sce_list), ceiling(seq_along(sce_list)/batch_size))
  integrated_list <- list()
  
  for(i in seq_along(batches)){
    message("Processing batch ", i, "/", length(batches))
    batch <- sce_list[batches[[i]]]
    
    anchors <- FindIntegrationAnchors(
      object.list = batch,
      reduction = "rpca",
      dims = 1:pcaNumber,
      k.filter = 100,
      verbose=F
    )
    
    combined <- IntegrateData(anchorset = anchors, dims = 1:pcaNumber, verbose=F)
    
    DefaultAssay(combined) <- "integrated"
    combined <- ScaleData(combined, verbose=F)
    combined <- RunPCA(combined, npcs=pcaNumber, verbose=F)
    
    integrated_list[[i]] <- combined
    rm(batch, anchors, combined)
    gc()
  }
  
  
  message("=== Final integration ===")
  anchors_final <- FindIntegrationAnchors(
    object.list = integrated_list,
    reduction = "rpca",                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
    dims = 1:pcaNumber,
    k.filter = 50,
    k.anchor = 5,
    verbose=F
  )

  inter <- IntegrateData(anchorset = anchors_final, dims = 1:pcaNumber, verbose=F)
  DefaultAssay(inter) <- "integrated"
  SaveH5Seurat(inter, filename = file.path(targetfold, paste0(pcaNumber, "_rpc0508.h5Seurat")))
  

  inter <- ScaleData(inter, vars.to.regress=c("percent_mt","nCount_RNA"), verbose=F)
  inter <- RunPCA(inter, npcs=pcaNumber, verbose=F)
  inter <- FindNeighbors(inter, dims = 1:pcaNumber)
  inter <- FindClusters(inter, resolution = 0.8)
  inter <- RunUMAP(inter, dims=1:pcaNumber, verbose=F)
  plot_umap_gg(inter,reduction ='umap',pname="ggInter",pcaNumber=pcaNumber)
  
  
  saveRDS(inter@reductions$pca, file.path(targetfold, "RPCA_integrated_PCA.rds"))
  saveRDS(inter@reductions$umap, file.path(targetfold, "RPCA_integrated_UMAP.rds"))
  saveRDS(inter@meta.data, file.path(targetfold, "metadata_clusters.rds"))
  saveRDS(inter, file.path(targetfold, "final_integrated_object.rds"))
  
  message("=== rpca integration has been done ===")
  return(inter)
}

result <-Seu2Inter_Lisi_fixed(input = input, pcaNumber=50, batch_size=5) 